issue_body:
Updating a vertex by setting a property to the same value and committing increments the record version. This looks like a no-op from a data perspective but still produces a new version, which in a clustered setup triggers synchronization of the vertex across nodes unnecessarily.

Expected behavior:
If no effective data change occurs (property set to its current value), the record version should remain unchanged and no update/synchronization should be triggered.

Actual behavior:
The record version increases after committing even though the property value is unchanged, which triggers downstream sync logic between nodes.

Environment:
OrientDB:  3.2.43
Java: 21

Minimal reproduction (JUnit):
```java
import com.orientechnologies.orient.core.config.OGlobalConfiguration;
import com.orientechnologies.orient.core.db.ODatabaseSession;
import com.orientechnologies.orient.core.db.ODatabaseType;
import com.orientechnologies.orient.core.db.OrientDB;
import com.orientechnologies.orient.core.db.OrientDBConfig;
import com.orientechnologies.orient.core.metadata.schema.OSchema;
import com.orientechnologies.orient.core.metadata.security.OUser;
import com.orientechnologies.orient.core.record.OVertex;

import java.util.Map;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class RecordVersionIssueTest {

    private static final String ENTITY_CLASS = "Entity";

    private static final String ENTITY_NAME = "EntityName";

    private ODatabaseSession db;

    private OVertex entity;

    private OrientDB orientDB;

    private static final OrientDBConfig CONFIG = OrientDBConfig.builder()
            .addConfig(OGlobalConfiguration.CREATE_DEFAULT_USERS, true)
            .build();

    @BeforeEach
    void setUp() {
        orientDB = new OrientDB("memory:", OUser.ADMIN, OUser.ADMIN, CONFIG);
        orientDB.createIfNotExists("test", ODatabaseType.MEMORY);
        db = orientDB.open("test", "admin", "admin");

        OSchema schema = db.getMetadata().getSchema();
        if (!schema.existsClass(ENTITY_CLASS)) {
            db.command("CREATE CLASS " + ENTITY_CLASS + " EXTENDS V");
        }

        entity = db.newVertex(ENTITY_CLASS);
        entity.setProperty("name", ENTITY_NAME);
        db.save(entity);
        db.commit();
    }

    @Test
    void versionShouldNotIncrementWhenSettingSameValue() {
        final String query = "SELECT FROM :id";

        try (var rs = db.query(query, Map.of("id", entity.getIdentity())).vertexStream()) {
            final OVertex vertex = rs.findFirst().orElseThrow();
            final int initialVersion = vertex.getRecord().getVersion();
            assertEquals(1, initialVersion, "Version should be 1 after creation");

            // Set the same value
            vertex.setProperty("name", ENTITY_NAME);
            db.save(vertex);
            db.commit();
        }

        try (var rs = db.query(query, Map.of("id", entity.getIdentity())).vertexStream()) {
            final OVertex vertex = rs.findFirst().orElseThrow();
            final int version = vertex.getRecord().getVersion();
            // Fails: version becomes 2 although nothing changed
            assertEquals(1, version, "Version should remain 1 after setting the same property again");
        }
    }

    @AfterEach
    void tearDown() {
        db.command("DELETE VERTEX " + ENTITY_CLASS);
        db.close();
        orientDB.close();
    }
}

