302	//Specular fresnel computation
303	vec3 F_Shlick(float vh,	vec3 F0){
304		float fresnelFact = pow(2.0, (-5.55473*vh - 6.98316) * vh);
305		return mix(F0, vec3(1.0, 1.0, 1.0), fresnelFact);
306	}
