308	vec3 sphericalHarmonics( const in vec3 normal, const vec3 sph[9] ){
309	    float x = normal.x;
310	    float y = normal.y;
311	    float z = normal.z;
312	
313	    vec3 result = (
314	        sph[0] +
315	
316	        sph[1] * y +
317	        sph[2] * z +
318	        sph[3] * x +
319	
320	        sph[4] * y * x +
321	        sph[5] * y * z +
322	        sph[6] * (3.0 * z * z - 1.0) +
323	        sph[7] * (z * x) +
324	        sph[8] * (x*x - y*y)
325	    );
326	
327	    return max(result, vec3(0.0));
328	}
