579	        float fDelta2 = pt2.x - pt2.y;
580	        float fDelta1 = pt1.x - pt1.y;
581	
582	        float fDenominator = fDelta2 - fDelta1;
583	
584	        fParallaxAmount = (pt1.x * fDelta2 - pt2.x * fDelta1 ) / fDenominator;
