@Test
	public  void testNestedGetDeadlock() throws Exception {
		final Cache<String, String> cache = new LRUCache<>(100);

		final String key1 = "key1";
		final String key2 = "key2";

		ExecutorService executor = Executors.newFixedThreadPool(2);
		CountDownLatch latch = new CountDownLatch(2);
		AtomicInteger deadlockDetected = new AtomicInteger(0);

		// 线程1：key1 -> key2
		executor.submit(() -> {
			try {
				String result = cache.get(key1, new Func0<String>() {
					@Override
					public String call() throws Exception {
						Thread.sleep(100);
						return cache.get(key2, () -> "value2") + "-nested"; //循环调用get方法，获取key2
					}
				});
				System.out.println("线程1完成: " + result);
			} catch (Exception e) {
				System.err.println("线程1异常: " + e.getMessage());
				if (e.getMessage() != null && e.getMessage().contains("deadlock")) {
					deadlockDetected.incrementAndGet();
				}
			}
		});

		// 线程2：key2 -> key1
		executor.submit(() -> {
			try {
				String result = cache.get(key2, new Func0<String>() {
					@Override
					public String call() throws Exception {
						//Thread.sleep(100);
						return cache.get(key1, () -> "value1") + "-nested"; //循环调用get方法，获取key1
					}
				});
				System.out.println("线程2完成: " + result);
			} catch (Exception e) {
				System.err.println("线程2异常: " + e.getMessage());
				if (e.getMessage() != null && e.getMessage().contains("deadlock")) {
					deadlockDetected.incrementAndGet();
				}
			} finally {
				latch.countDown();
			}
		});

		// 设置超时检测死锁
		if (!latch.await(5, TimeUnit.SECONDS)) {
			System.out.println("检测到可能的死锁!");
			deadlockDetected.incrementAndGet();
		}

		executor.shutdown();
		System.out.println("死锁检测次数: " + deadlockDetected.get());
	}
```
线程1首先获取key1的锁，线程2首先获取key2的锁。由于有循环调用，线程1准备获取key2的锁，线程2准备获取key1的锁，此时发生了死锁。

