```java
@Test
void testMultimapCacheError() throws Exception {
    {
        final RListMultimapCacheReactive<String, String> multimap = redissonClient.getListMultimapCache("getListMultimapCache", StringCodec.INSTANCE);
        multimap.putAll("key", List.of("A", "B")).block();
