        final RSetMultimapCacheReactive<String, String> multimap = redissonClient.getSetMultimapCache("getSetMultimapCache", StringCodec.INSTANCE);
        multimap.putAll("key", Set.of("A", "B")).block();
        assertEquals(Set.of("A", "B"), multimap.get("key").readAll().block());
    }
}

@Test
void testMultimapOk() throws Exception {
    {
        final RListMultimapReactive<String, String> multimap = redissonClient.getListMultimap("getListMultimap", StringCodec.INSTANCE);
        multimap.putAll("key", List.of("A", "B")).block();
        assertEquals(multimap.get("key").readAll().block(), List.of("A", "B"));
