+                    int longSize = 8;
+                    masm.mov(64, scratch, sp);
+                    AArch64Address address = AArch64Address.createPostIndexedImmediateAddress(scratch, longSize);
+                    try (ScratchRegister sc2 = masm.getScratchRegister()) {
